<?php
require __DIR__.'/bootstrap.php';require_admin();
$error='';$notice='';
$statuses=['pending','confirmed','preparing','ready','completed','cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');
 try{
 if($action==='save_product'){
  $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$category=(int)($_POST['category_id']??0);$special=isset($_POST['special'])?1:0;$available=isset($_POST['available'])?1:0;
  $q=$db->prepare('SELECT id FROM categories WHERE id=?');$q->execute([$category]);
  if($name===''||mb_strlen($name)>150||$price===false||$price<0||$category<1||!$q->fetch()){throw new RuntimeException('Enter a valid name, price and category.');}
  if($id>0){$q=$db->prepare('UPDATE products SET category_id=?,name=?,description=?,price=?,is_special=?,is_available=? WHERE id=?');$q->execute([$category,$name,$description,$price,$special,$available,$id]);}
  else{$q=$db->prepare('INSERT INTO products(category_id,name,description,price,is_special,is_available) VALUES(?,?,?,?,?,?)');$q->execute([$category,$name,$description,$price,$special,$available]);}
  $notice='Product saved.';
 }elseif($action==='status'){
  $id=(int)($_POST['order_id']??0);$status=(string)($_POST['status']??'');
  if($id<1||!in_array($status,$statuses,true)){throw new RuntimeException('Invalid order update.');}
  $q=$db->prepare('UPDATE orders SET status=? WHERE id=?');$q->execute([$status,$id]);$notice='Order status updated.';
 }else{throw new RuntimeException('Unknown action.');}
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Unable to save changes.';}
}
$categories=$db->query('SELECT id,name FROM categories ORDER BY id')->fetchAll();
$products=$db->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();
$orders=$db->query('SELECT id,customer_name,fulfillment,total,status,created_at FROM orders ORDER BY id DESC LIMIT 50')->fetchAll();
$counts=$db->query("SELECT COUNT(*) orders_count,COALESCE(SUM(CASE WHEN status <> 'cancelled' THEN total ELSE 0 END),0) order_value FROM orders")->fetch();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard | The Yummy House</title><link rel="stylesheet" href="../assets/style.css"><style>.admin-table{width:100%;border-collapse:collapse}.admin-table th,.admin-table td{text-align:left;padding:10px;border-bottom:1px solid #eadccc}.scroll{overflow-x:auto}.admin-table form{display:flex;gap:8px}.admin-table select{min-width:135px}.admin-table button{white-space:nowrap}.stats{display:flex;gap:20px;flex-wrap:wrap}.stats>div{padding:18px;background:#f5e7d3;border-radius:12px}.admin-layout{display:grid;grid-template-columns:1fr;gap:24px}.admin-layout .panel{max-width:none;width:100%}</style></head><body><header class="top"><a class="brand" href="index.php">Yummy House · Admin</a><nav class="nav"><a href="../index.php">View store</a><form method="post" action="logout.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button type="submit">Log out</button></form></nav></header><main class="container"><h1>Restaurant dashboard</h1><p class="muted">Manage products, specials, availability and incoming orders.</p><?php if($notice):?><p role="status"><?=h($notice)?></p><?php endif;?><?php if($error):?><p role="alert"><?=h($error)?></p><?php endif;?><div class="stats"><div><strong><?= (int)$counts['orders_count'] ?></strong><p>Orders received</p></div><div><strong>R<?=number_format($counts['order_value'],2)?></strong><p>Non-cancelled order value (not confirmed revenue)</p></div><div><strong><?=count($products)?></strong><p>Listed products</p></div></div><div class="admin-layout"><section class="panel"><h2>Recent orders</h2><div class="scroll"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Method</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?= (int)$o['id'] ?></td><td><?=h($o['customer_name'])?></td><td><?=h($o['fulfillment'])?></td><td>R<?=number_format($o['total'],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach($statuses as $s):?><option value="<?=h($s)?>" <?=$o['status']===$s?'selected':''?>><?=h(ucfirst($s))?></option><?php endforeach;?></select><button type="submit">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Add a product</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save_product"><label for="name">Product name</label><input id="name" name="name" required maxlength="150"><label for="description">Description</label><textarea id="description" name="description"></textarea><label for="price">Price (ZAR)</label><input id="price" name="price" type="number" step="0.01" min="0" required><label for="category">Category</label><select id="category" name="category_id"><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select><p><label><input style="width:auto" type="checkbox" name="special"> Weekly special</label><label><input style="width:auto" type="checkbox" name="available" checked> Available to order</label></p><button type="submit">Add product</button></form></section><section class="panel"><h2>Products & availability</h2><p class="muted">Update prices, specials and availability. Product names and descriptions can be edited below.</p><?php foreach($products as $p):?><details style="border-bottom:1px solid #eadccc;padding:12px 0"><summary><?=h($p['name'])?> · R<?=number_format($p['price'],2)?> <?= $p['is_available']?'':'· Unavailable' ?></summary><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><label>Name</label><input name="name" value="<?=h($p['name'])?>" required><label>Description</label><textarea name="description"><?=h($p['description'])?></textarea><label>Price</label><input name="price" type="number" step="0.01" min="0" value="<?=h($p['price'])?>" required><label>Category</label><select name="category_id"><?php foreach($categories as $c):?><option value="<?=(int)$c['id']?>" <?=$c['id']==$p['category_id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><p><label><input style="width:auto" type="checkbox" name="special" <?=$p['is_special']?'checked':''?>> Weekly special</label><label><input style="width:auto" type="checkbox" name="available" <?=$p['is_available']?'checked':''?>> Available</label></p><button type="submit">Save changes</button></form></details><?php endforeach;?></section></div></main></body></html>
